# Social trademarks and progress geometry retain their original shapes.
EXEMPT = {'Facebook','Instagram','Linkedin','Youtube','Loader2'}
names = set()
for file in pathlib.Path('src').rglob('*'):
 if file.suffix not in ('.tsx','.ts'): continue
 for match in re.finditer(r'import\s+(?:type\s+)?\{([^}]+)\}\s*from\s*[\"\x27]lucide-react[\"\x27]',file.read_text(),re.S):
  names.update(item.strip().split(' as ')[0].removeprefix('type ').strip() for item in match[1].split(',') if item.strip())
names.discard('LucideIcon')
names.update(['Book','RectangleHorizontal','Languages','Settings','FolderOpen'])

def kebab(name):
 return re.sub(r'([a-z0-9])([A-Z])',r'\1-\2',name).lower()

TAGS={'path','g','circle','rect','line','polyline','polygon','ellipse'}
ATTRS={'d','fill','fill-rule','clip-rule','stroke','stroke-width','stroke-linecap','stroke-linejoin','stroke-miterlimit','opacity','fill-opacity','stroke-opacity','transform','cx','cy','r','rx','ry','x','y','x1','x2','y1','y2','width','height','points','class'}
CAMEL={'fill-rule':'fillRule','clip-rule':'clipRule','stroke-width':'strokeWidth','stroke-linecap':'strokeLinecap','stroke-linejoin':'strokeLinejoin','stroke-miterlimit':'strokeMiterlimit','fill-opacity':'fillOpacity','stroke-opacity':'strokeOpacity'}
def tree(node):
 assert node.tag in TAGS,(node.tag,node.attrib)
 assert not (node.text or '').strip()
 props={}
 for key,value in node.attrib.items():
  assert key in ATTRS,(key,value)
  assert not re.search(r'url\(|https?:|javascript:|[<>]',value,re.I),value
  if key != 'class': props[CAMEL.get(key,key)]=value
 return [node.tag,props,[tree(child) for child in node]]
metadata=[]; manifest=[]; coverage={}
for id,prefix,label,description,suffix in FAMILIES:
 raw=(SOURCE/(prefix+'.json')).read_bytes(); data=json.loads(raw); available=data['icons']; selected={}; mapping={}; missing=[]
 for name in sorted(names-EXEMPT):
  candidates=[kebab(name)]+ALIASES.get(name,'').split(',')
  candidates=list(dict.fromkeys(x for x in candidates if x))
  found=None
  for candidate in candidates:
   variants=[candidate+suffix,candidate]
   if prefix=='fluent': variants=[candidate+f'-{size}-regular' for size in [24,20,16,32]]
   for v in variants:
    if v in available: found=v; break
   if found:break
  if found:
   mapping[name]=found
   if found not in selected:
    icon=available[found]; doc=ET.fromstring('<g>'+icon['body']+'</g>')
    selected[found]={'nodes':[tree(c) for c in doc], 'width':icon.get('width',data.get('width',24)), 'height':icon.get('height',data.get('height',24))}
    assert not any(icon.get(k) for k in ['rotate','hFlip','vFlip'])
  else: missing.append(name)
 result={'icons':selected,'mapping':mapping}
 TARGET.mkdir(parents=True,exist_ok=True); (TARGET/(id+'.json')).write_text(json.dumps(result,separators=(',',':'))+'\n')
 metadata.append({'id':id,'name':label,'description':description,'author':data['info']['author']['name'],'license':data['info']['license']['spdx']})
 manifest.append({'id':id,'prefix':prefix,'revision':REVISION,'source':f'https://github.com/iconify/icon-sets/blob/{REVISION}/json/{prefix}.json','sha256':hashlib.sha256(raw).hexdigest(),'info':data['info'],'mappedCount':len(mapping),'missing':missing})
 coverage[id]=missing; print(id,len(mapping),'missing',','.join(missing))
pathlib.Path('src/lib/icons/families.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2)+'\n')
manifest_path = pathlib.Path('docs/icons/provenance.json')
previous = {entry['id']:entry for entry in json.loads(manifest_path.read_text())} if manifest_path.exists() else {}
for entry in manifest:
 old = previous.get(entry['id'], {})
 if old.get('sha256') == entry['sha256']:
  for key in ['licenseSource','licenseSha256','retrieved']:
   if key in old: entry[key] = old[key]
manifest_path.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('/private/tmp/webprinter-icon-coverage.json').write_text(json.dumps(coverage,indent=2))
# One compatibility entry point, with tree-shakable static named exports.
exports=["// Generated by scripts/icons/generate-icon-families.py; preserves Lucide props and types.","import * as Base from '@webprinter/lucide-base';", "import { themedIcon } from './IconFamily';", "export * from '@webprinter/lucide-base';"]
for name in sorted(names-EXEMPT): exports.append(f'export const {name} = /* @__PURE__ */ themedIcon(\'{name}\', Base.{name});')
pathlib.Path('src/components/icons/index.ts').write_text('\n'.join(exports)+'\n')
